insert into story_nodes (event_id, node_key, body, choices)
select id, $k$start$k$, $t$A rival has opened nearby, and {venture} is seeing fewer customers than usual. {name} has a few days to react and asks for your advice.$t$, $j$[{"label": "Advise {name} to cut prices to keep customers coming", "venture_mult": {"mult": 0.85, "days": 6}, "sets_flag": "cut_prices", "narrative": "{name} keeps the customers but earns less on each sale, so profits stay lower for the week."}, {"label": "Advise {name} to spend on promotion (flyers, WhatsApp status, a sign)", "cash_pct_capital": -0.04, "venture_mult": {"mult": 1.1, "days": 6}, "venture_note": "Promotion spend", "sets_flag": "promoted_business", "narrative": "It costs upfront, but people notice. Sales hold up and edge above normal."}, {"label": "Advise {name} to hold prices and wait it out", "venture_mult": {"mult": 0.6, "days": 6}, "sets_flag": "held_prices_in_slump", "narrative": "{name} protects their margins but loses a lot of customers while waiting."}]$j$::jsonb from story_events where event_key = $k$venture_slump$k$
on conflict (event_id, node_key) do update set body = excluded.body, choices = excluded.choices;

insert into story_events (event_key, category, trigger_type, trigger_config, eligibility_config, character_key, title, intro, entry_node)
values ($k$venture_big_order$k$, $k$venture_event$k$, $k$venture_event$k$, $j${}$j$::jsonb, $j${"venture_categories": ["retail", "services", "tech"]}$j$::jsonb, $k$inner_voice$k$, $t$A big order for {venture}$t$, $t$A customer wants a lot more than usual.$t$, 'start')
on conflict (event_key) do update set category = excluded.category, trigger_type = excluded.trigger_type, trigger_config = excluded.trigger_config,
  eligibility_config = excluded.eligibility_config, character_key = excluded.character_key, title = excluded.title, intro = excluded.intro;
insert into story_nodes (event_id, node_key, body, choices)
select id, $k$start$k$, $t$A customer asks {name} for a big order from {venture}. {name} would need to spend about 8% of their capital upfront to fill it, and it pays back well when delivered. What do you advise?$t$, $j$[{"label": "Advise {name} to take the order", "cash_pct_capital": -0.08, "venture_note": "Stock and materials for the big order", "sets_flag": "took_big_order", "narrative": "{name} puts the money in and gets to work. Payment is due in a day or so."}, {"label": "Advise {name} to take it, but ask for a 50% deposit first", "requires_flag": "learned_breakeven_math", "cash_pct_capital": -0.04, "reputation_delta": 1, "venture_note": "Stock for the big order (after deposit)", "sets_flag": "took_big_order_with_deposit", "narrative": "The deposit covers half the costs, so {name} puts in less of their own cash and carries less risk."}, {"label": "Advise {name} to decline politely", "sets_flag": "declined_big_order", "narrative": "{name} keeps their cash safe and carries on as normal."}]$j$::jsonb from story_events where event_key = $k$venture_big_order$k$
on conflict (event_id, node_key) do update set body = excluded.body, choices = excluded.choices;

insert into story_events (event_key, category, trigger_type, trigger_config, eligibility_config, character_key, title, intro, entry_node)
values ($k$venture_big_order_paid$k$, $k$consequence$k$, $k$flag_delay$k$, $j${"after_flag": "took_big_order", "delay_real_days": 1}$j$::jsonb, $j${}$j$::jsonb, $k$inner_voice$k$, $t$Big order delivered$t$, $t$$t$, 'start')
