insert into story_nodes (event_id, node_key, body, choices)
select id, $k$start$k$, $t$The customer pays {name} for the big order for {venture}.$t$, $j$[{"label": "Collect the payment", "cash_pct_capital": 0.16, "venture_note": "Big order payment", "narrative": "Delivered and paid. Taking on the risk paid off this time."}]$j$::jsonb from story_events where event_key = $k$venture_big_order_paid$k$
on conflict (event_id, node_key) do update set body = excluded.body, choices = excluded.choices;

