values ($k$venture_big_order_paid_deposit$k$, $k$consequence$k$, $k$flag_delay$k$, $j${"after_flag": "took_big_order_with_deposit", "delay_real_days": 1}$j$::jsonb, $j${}$j$::jsonb, $k$inner_voice$k$, $t$Big order delivered$t$, $t$$t$, 'start')
on conflict (event_key) do update set category = excluded.category, trigger_type = excluded.trigger_type, trigger_config = excluded.trigger_config,
