insert into story_nodes (event_id, node_key, body, choices)
select id, $k$start$k$, $t$The customer pays {name} the balance of the big order for {venture}.$t$, $j$[{"label": "Collect the payment", "cash_pct_capital": 0.16, "venture_note": "Big order balance", "narrative": "Delivered and paid. The deposit meant {name} risked far less of their own cash."}]$j$::jsonb from story_events where event_key = $k$venture_big_order_paid_deposit$k$
on conflict (event_id, node_key) do update set body = excluded.body, choices = excluded.choices;

insert into story_events (event_key, category, trigger_type, trigger_config, eligibility_config, character_key, title, intro, entry_node)
values ($k$venture_profit_decision$k$, $k$venture_payout$k$, $k$venture_payout$k$, $j${}$j$::jsonb, $j${}$j$::jsonb, $k$inner_voice$k$, $t$Profit at {venture}$t$, $t$The books are looking healthy.$t$, 'start')
on conflict (event_key) do update set category = excluded.category, trigger_type = excluded.trigger_type, trigger_config = excluded.trigger_config,
  eligibility_config = excluded.eligibility_config, character_key = excluded.character_key, title = excluded.title, intro = excluded.intro;
insert into story_nodes (event_id, node_key, body, choices)
select id, $k$start$k$, $t$About {retained} of profit has built up inside {venture}. It is not in {name}'s pocket yet. What do you advise {name} to do with it?$t$, $j$[{"label": "Advise {name} to take it all home", "retained_withdraw_pct": 1, "sets_flag": "withdrew_profits", "narrative": "{name} pays themselves in full. Cash goes up now, and the business keeps running on what it already has."}, {"label": "Advise {name} to reinvest it all in the business", "retained_reinvest_pct": 1, "sets_flag": "reinvested_profits", "narrative": "Every kwacha goes back in. The business grows, though with no cash in {name}'s pocket and returns that taper off as it gets bigger."}, {"label": "Advise {name} to split it: half home, half reinvested", "retained_withdraw_pct": 0.5, "retained_reinvest_pct": 0.5, "sets_flag": "split_profits", "narrative": "A balanced choice: {name} enjoys some of the reward while the business keeps growing."}, {"label": "Advise {name} to leave it in the business as a safety buffer", "sets_flag": "kept_profit_buffer", "narrative": "The profit stays put. If something goes wrong at {venture}, it will be paid from here first, before {name} touches their own cash."}]$j$::jsonb from story_events where event_key = $k$venture_profit_decision$k$
on conflict (event_id, node_key) do update set body = excluded.body, choices = excluded.choices;

